        public virtual void Save()
        {
            if (context == null)
                throw new InvalidOperationException("Context has not been initialized.");
            context.SaveChanges();
        }

        public void BeginTransaction()
        {
            // 1) Arranca la tx ADO.NET
            _db.BeginTransaction();
            // 2) Se la “enchufa” a EF Core
            context.Database.UseTransaction(_db.Transaction);
        }
        public void Commit()
        {
            // asegurar primero el Save, luego confirmar la tx ADO.NET
            Save();
            _db.CommitTransaction();
        }

        public void Rollback()
        {
            _db.RollbackTransaction();
        }

        public string ObtenerDbUserId()
        {
            var oracleConn = _db.Connection;
            var builder = new OracleConnectionStringBuilder(oracleConn.ConnectionString);
            return builder.UserID;
        }

